package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's today; with an as-of date, that date stands for it (and archived is as at the end of it). */
public class LoadToday {
    public void service(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Sheets sheets, AsOfView view,
            ObjectResponse<TodayResponse> response) {
        LocalDate date = AsOfView.parse(asOf);
        response.send(date == null ? TodayResponse.of(sheetId, sheets) : view.today(sheetId, date));
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidateToday {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody TodayRequest request, Out<LocalDate> today, Out<TodayRequest> body, Settings settings)
            throws InvalidTodayException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        body.set(request); // who changes it, for the audit
        String raw = request.today() == null ? "" : request.today().trim();
        if (raw.isEmpty()) {
            today.set(LocalDate.now()); // blank takes the default: the real date
            return;
        }
        try {
            today.set(LocalDate.parse(raw));
        } catch (DateTimeParseException e) {
            throw new InvalidTodayException(raw);
        }
    }
}
package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.period.PeriodCloser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveToday {
    public void save(@PathVariable("sheetId") String sheetId, @Val LocalDate today, Sheets sheets,
            @Val TodayRequest request, @Val RollupFigures before, Rollup rollup, PeriodCloser closer, Claims claims,
            ObjectResponse<TodayResponse> response) {
        // Each person's due-total as it stood on the day being left, before the change takes effect.
        rollup.recordSnapshots(sheetId, request.user(), before);
        sheets.setToday(sheetId, today);
        // A change of today releases every open editor's lock.
        claims.unlockAll(sheetId);
        closer.closeDue(sheetId, request.user());
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(TodayResponse.of(sheetId, sheets));
    }
}
