import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

export type SheetToday = { sheet: string; today: string; archived: boolean };

export const sheetTodayKey = (sheet: string, asOf = '') => ['sheet', sheet, 'today', asOf] as const;

/** The sheet's today (YYYY-MM-DD; the as-of date while one is set). Every date decision and default date on screen reads this —
 *  never `new Date()`. Undefined while loading. */
export function useSheetToday(sheet: string): string | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.today;
}

/** Whether the sheet is archived (everything visible, every change refused). Undefined while loading. */
export function useSheetArchived(sheet: string): boolean | undefined {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: sheetTodayKey(sheet, asOf),
    queryFn: () => getJson<SheetToday>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/today`, asOf)),
    enabled: sheet !== '',
  });
  return data?.archived;
}
import { QueryClient } from '@tanstack/react-query';

// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
// retry:false + no focus refetching keep the e2e runs deterministic.
export const queryClient = new QueryClient({
  defaultOptions: {
    queries: { retry: false, refetchOnWindowFocus: false },
    mutations: { retry: false },
  },
});
import { useRef } from 'react';

/** Guards a form's submit so a second submit made before the first has answered (a double click)
 *  is ignored: the store gets one record, not two. A ref, not mutation state, so it holds even
 *  for two clicks landing before the next render. */
export function useSubmitOnce(): (run: () => Promise<unknown>) => void {
  const busy = useRef(false);
  return (run) => {
    if (busy.current) return;
    busy.current = true;
    run()
      .catch(() => {
        // the mutation shows its own error
      })
      .finally(() => {
        busy.current = false;
      });
  };
}

